package Program.service; import Program.model.*; import Program.utils.FileManager; import java.time.LocalDate; import java.util.*;
public class ReportService {private final TransactionService transactions=new TransactionService(); public FinancialReport create(String user,LocalDate from,LocalDate to){List<Transaction> list=transactions.all(user);double income=list.stream().filter(t->t instanceof Income).filter(t->inRange(t,from,to)).mapToDouble(Transaction::getAmount).sum();double expense=list.stream().filter(t->t instanceof Expense).filter(t->inRange(t,from,to)).mapToDouble(Transaction::getAmount).sum();return new FinancialReport(from,to,income,expense);} private boolean inRange(Transaction t,LocalDate f,LocalDate to){return !t.getDate().isBefore(f)&&!t.getDate().isAfter(to);} public void save(FinancialReport r){FileManager.append("reports/monthly_reports.txt",r.generateReport());}}
